"use client";

import React from "react";
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import OrderCard from "@/components/orders/OrderCard";
import { SearchBar } from "@/components/ui/SearchBar";
import { FloatingActionButton } from "@/components/ui/FloatingActionButton";
import { fetchOrders } from "@/features/orders/ordersSlice";

export default function OrdersPage() {
   const dispatch = useAppDispatch();
     const loadedOnceRef = React.useRef(false);
     const loading = useAppSelector((s) => s.orders.loadingOrders);

  const orders = useAppSelector((s) => s.orders.orders);
  const [q, setQ] = React.useState("");



  React.useEffect(() => {
    if (loadedOnceRef.current) return;
    loadedOnceRef.current = true;

    dispatch(fetchOrders());
  }, [dispatch]);

  return (
    <div>
      <div className="app-card p-3 mb-3">
        <SearchBar value={q} onChange={setQ} placeholder="Αναζήτηση (ID, συνταγή, όνομα, ΑΜΚΑ…)" />
      </div>

      {orders.length ? (
        orders.map((o) => <OrderCard key={o.id}
                                      order={o}
                                      onDelete={(id) => {
                                        // 1) optimistic remove from redux
                                        // 2) call backend delete endpoint (if exists)
                                      }} />)
      ) : (
        <div className="app-card p-4 text-center text-secondary">
          Δεν βρέθηκαν παραγγελίες.
        </div>
      )}

      <FloatingActionButton href="/orders/new" ariaLabel="Νέα παραγγελία (Επιλογή πλατφόρμας)" />
    </div>
  );
}
